import{_ as s,o as a,c as i,aN as t}from"./chunks/framework.D31DlcCL.js";const u=JSON.parse('{"title":"文章精选系统 (Article Selection System)","description":"","frontmatter":{},"headers":[],"relativePath":"posts/article-selection-system.md","filePath":"posts/article-selection-system.md","lastUpdated":null}'),l={name:"posts/article-selection-system.md"};function n(o,e,r,d,c,p){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="文章精选系统-article-selection-system" tabindex="-1">文章精选系统 (Article Selection System) <a class="header-anchor" href="#文章精选系统-article-selection-system" aria-label="Permalink to &quot;文章精选系统 (Article Selection System)&quot;">​</a></h1><p>这是一个基于 VitePress 的智能文章精选系统，通过文章的<strong>发布时间</strong>和<strong>阅读量</strong>两个维度进行加权评分，实现动态排序和精选展示。</p><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h2><ol><li><p><strong>智能评分算法</strong>：</p><ul><li><strong>最新发布权重 (40%)</strong>：鼓励展示新鲜内容。</li><li><strong>阅读数量权重 (60%)</strong>：优先展示受关注度高的热门内容。</li><li>评分公式：<code>Score = (NormalizedTime * 0.4 + NormalizedViews * 0.6) * 100</code></li></ul></li><li><p><strong>数据采集与异常过滤</strong>：</p><ul><li>自动读取 <code>docs/posts/*.md</code> 的 Frontmatter 日期。</li><li>从 <code>docs/public/data/article-stats.json</code> 获取实时/模拟阅读量。</li><li>自动过滤日期格式错误、阅读量异常（负数或过大）的无效文章。</li></ul></li><li><p><strong>动态排序与展示</strong>：</p><ul><li>提供 Vue 组件 <code>FeaturedArticles</code>，支持按“综合热度”、“最新发布”、“最多阅读”进行即时排序。</li><li>响应式设计，适配桌面与移动端。</li></ul></li><li><p><strong>自动更新机制</strong>：</p><ul><li>集成在 <code>npm run docs:dev</code> 和 <code>npm run docs:build</code> 中。</li><li>每次构建前自动生成最新的 <code>featured-articles.json</code>。</li></ul></li></ol><h2 id="目录结构" tabindex="-1">目录结构 <a class="header-anchor" href="#目录结构" aria-label="Permalink to &quot;目录结构&quot;">​</a></h2><ul><li><code>scripts/selection-engine.js</code>: 核心评分引擎与列表生成逻辑。</li><li><code>scripts/mock-stats.js</code>: 模拟阅读量数据生成器（开发/测试用）。</li><li><code>tests/selection.test.js</code>: 算法单元测试。</li><li><code>docs/.vitepress/theme/components/FeaturedArticles.vue</code>: 可视化展示组件。</li><li><code>docs/public/data/article-stats.json</code>: 文章统计原始数据。</li><li><code>docs/public/data/featured-articles.json</code>: 生成的精选列表缓存。</li></ul><h2 id="使用方法" tabindex="-1">使用方法 <a class="header-anchor" href="#使用方法" aria-label="Permalink to &quot;使用方法&quot;">​</a></h2><h3 id="运行测试" tabindex="-1">运行测试 <a class="header-anchor" href="#运行测试" aria-label="Permalink to &quot;运行测试&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:featured</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="更新精选列表" tabindex="-1">更新精选列表 <a class="header-anchor" href="#更新精选列表" aria-label="Permalink to &quot;更新精选列表&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:featured</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="手动模拟数据" tabindex="-1">手动模拟数据 <a class="header-anchor" href="#手动模拟数据" aria-label="Permalink to &quot;手动模拟数据&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/mock-stats.js</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>生产环境下，<code>article-stats.json</code> 的数据应由真实的统计工具（如百度统计、GA 或 数据库 API）定期更新。</li><li>评分算法的权重可在 <code>scripts/selection-engine.js</code> 中根据需求调整。</li></ul>',15)])])}const m=s(l,[["render",n]]);export{u as __pageData,m as default};
